APP_SOURCE="def certificate_app():\n    raw = certificate_text(['shell', '-T', 'pidof', 'com.kardinal.vpncontrol'])\n    if not re.fullmatch('[1-9][0-9]*', raw):\n        raise ValueError('owner_admission_app_process_unknown')\n    pid = int(raw)\n    table = certificate_text(['shell', '-T', 'ps', '-A', '-o', 'PID,UID,NAME'])\n    rows = table.splitlines()\n    if not rows or rows[0].split() != ['PID', 'UID', 'NAME']:\n        raise ValueError('owner_admission_app_census_unknown')\n    found = []\n    pids = set()\n    for line in rows[1:]:\n        fields = line.split()\n        if len(fields) != 3 or not fields[0].isdigit() or (not fields[1].isdigit()) or (int(fields[0]) in pids):\n            raise ValueError('owner_admission_app_census_unknown')\n        pids.add(int(fields[0]))\n        if fields[2] == 'com.kardinal.vpncontrol':\n            found.append((int(fields[0]), int(fields[1])))\n    if len(found) != 1 or found[0][0] != pid or found[0][1] < 10000:\n        raise ValueError('owner_admission_app_process_unknown')\n    rawstat = certificate_text(['shell', '-T', 'cat', '/proc/' + str(pid) + '/stat'])\n    match = re.fullmatch(str(pid) + ' \\\\(([^()\\\\r\\\\n]+)\\\\) (.+)', rawstat)\n    if match is None:\n        raise ValueError('owner_admission_app_stat_unknown')\n    fields = match[2].split()\n    if len(fields) < 20 or not fields[19].isdigit() or int(fields[19]) <= 0:\n        raise ValueError('owner_admission_app_stat_unknown')\n    return {'pid': pid, 'uid': found[0][1], 'name': 'com.kardinal.vpncontrol', 'comm': match[1], 'startTicks': int(fields[19]), 'guestBootId': CERTIFICATE['facts']['guestBootId']}\n"
